  5761|    countTable('withdrawals', 'id'),
  5762|    countTable('wire_transfers', 'id'),
  5763|    countTable('notifications', 'id'),
  5764|  ]);
  5765|  // Get date range for visitor-related tables + waitlist + members
  5766|  const [laRows, aeRows, wlRows, memRows] = await Promise.all([
  5767|    queryRows('landing_analytics', 'id,created_at,event', 'created_at.asc', 5000),
