  5726|  }
  5727|  const headers = { apikey: key, Authorization: `Bearer ${key}`, Accept: 'application/json' };
  5728|  const countTable = async (table: string, col: string = 'id') => {
  5729|    try {
  5730|      const res = await fetch(`${url}/rest/v1/${table}?select=${encodeURIComponent(col)}`, { method: 'HEAD', headers: { ...headers, Prefer: 'count=exact', Range: '0-0' } });
  5731|      if (res.status === 404) return { table, count: null, status: 404, error: 'TABLE_NOT_FOUND' };
  5732|      const cr = res.headers.get('content-range');
  5733|      const total = cr ? parseInt(cr.split('/').pop() || '*', 10) : null;
  5734|      return { table, count: Number.isFinite(total) ? total : null, status: res.status, error: null };
  5735|    } catch (e) {
  5736|      return { table, count: null, status: null, error: e instanceof Error ? e.message : 'network_error' };
  5737|    }
