  5739|  const queryRows = async (table: string, select: string, order: string, limit: number) => {
  5740|    try {
  5741|      const res = await fetch(`${url}/rest/v1/${table}?select=${encodeURIComponent(select)}&order=${order}&limit=${limit}`, { headers });
  5742|      if (!res.ok) return { rows: [], status: res.status, error: `HTTP ${res.status}` };
  5743|      return { rows: await res.json(), status: res.status, error: null };
  5744|    } catch (e) {
  5745|      return { rows: [], status: null, error: e instanceof Error ? e.message : 'network_error' };
  5746|    }
